{
  "name": "demo",
  "description": "updated from Postman",
  "startStepId": "postman.echo_js",
  "maxRuntimeMs": 30000,
  "transitions": {
    "postman.echo_js": {
      "name": "Echo",
      "onSuccess": null,
      "onFailure": null,
      "onException": null,
      "maxTransitions": 1
    }
  },
  "active": true
}

{
  "content": "exports.run = async function(input) { return { ok: true, input, edited: true }; };",
  "contentType": "application/javascript",
  "isBinary": false
}

{
  "rest": { "hostname": "127.0.0.1", "port": 8901, "ssl": false },
  "database": { "type": "Sqlite", "filename": "./tempo.db" },
  "logging": { "consoleLogging": true, "fileLogging": true, "logDirectory": "./logs", "logFilename": "tempo.log" },
  "auth": { "issuer": "tempo", "signingKey": "tempo-development-key-override-for-production-use", "tokenExpirationMinutes": 1440 },
  "requestHistory": { "enabled": true, "maxRequestBodyBytes": 65536, "maxResponseBodyBytes": 65536, "retentionDays": 30, "pruneIntervalMinutes": 60 },
  "engine": { "queueEnabled": true, "maxConcurrentRuns": 4, "pollIntervalMs": 1000 },
  "hydration": { "seedDefaults": true, "defaultTenantName": "Default Tenant", "defaultAdminEmail": "admin@tempo.local", "defaultAdminPassword": "password", "defaultUserEmail": "user@tempo.local", "defaultUserPassword": "password" }
}
